--- from: Assets/BundleResources/Prefabs/Common/CommonPlayerHeadNode.prefab
---@class CommonPlayerHeadNode
---@field Env                            CommonPlayerHeadNode
---@field controller                        Engine.Modules.LuaBehaviour | Engine.UI.UILuaDialog
---@field Root                            UnityEngine.RectTransform
---@field DynamicFrame                    UnityEngine.RectTransform
---@field DynamicHead                    UnityEngine.RectTransform
---@field ImgFrame                        UnityEngine.RectTransform
---@field ImgheadIcon                    UnityEngine.RectTransform
local CommonPlayerHeadNode = Class("CommonPlayerHeadNode")
function CommonPlayerHeadNode:__init()
    ---@type integer @ 当前头像id
    self.avatarId = nil
    ---@type integer @ 当前头像框id
    self.frameId = nil
    self.listObjPoolsName = {}
end


function CommonPlayerHeadNode:__delete()
    self.avatarId = nil
    self.frameId = nil
    self.listObjPoolsName = nil

    self.controller = nil
end

---SetCallBack
---设置单击回调函数
---@param cb fun():void
function CommonPlayerHeadNode:SetCallBack(cb)
    self.__callback = cb
end

function CommonPlayerHeadNode:Awake()
    ---@type Engine.UI.ImageAlterable
    local imageAlterable = KTool.GetComponent(self.ImgheadIcon.gameObject, typeof(ImageAlterable))
    if not isNull(imageAlterable) then
        imageAlterable.IsAutoAlpha = true
    end
    ---@type Engine.UI.ImageAlterable
    local frameAlterable = KTool.GetComponent(self.ImgFrame.gameObject, typeof(ImageAlterable))
    if not isNull(frameAlterable) then
        frameAlterable.IsAutoAlpha = true
    end

    --- 克隆包含动态头像或边框资源的gameObject 会导致 索引丢失 这里 重新填充下
    if self.DynamicHead.childCount > 0 then
        self.dynamicAvatarGo = self.DynamicHead:GetChild(0).gameObject
        
    end
    if self.DynamicFrame.childCount > 0 then
        self.dynamicFrameGo = self.DynamicFrame:GetChild(0).gameObject
        
    end

    UIEventProxy.Create(self.controller.gameObject.transform:Find("Root").gameObject).onPointerClick = function()
        if type(self.__callback) == 'function' then
            self.__callback()
        end
    end
end

---刷新头像
function CommonPlayerHeadNode:FreshBaseUI()
    ---@type PlayerComponent
    local playerComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    local iconId = playerComp.playerDojo.playerAvatar
    local frameId = playerComp.playerDojo.playerAvatarFrame
    self:FreshHeadIcon(iconId)
    self:FreshFrame(frameId)
end

---@class CommonPlayerHeadNode.Data
---@field avatarId number
---@field frameId number

---传入id刷新头像和头像框
---@param avatarId string @ 道具表id（头像）
---@param frameId string @ 道具表id（头像框）
function CommonPlayerHeadNode:FreshAvatarFrame(avatarId, frameId)
    self:FreshHeadIcon(avatarId)
    self:FreshFrame(frameId)
end

---刷新头像
---@param id string @ 道具表id
---@param isHideFrame boolean @ 是否隐藏头像框，仅当做纯头像使用
function CommonPlayerHeadNode:FreshHeadIcon(id, isHideFrame)
    if checkInt(id) == 0 then
        ---@type PlayerComponent
        local playerComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
        id = PlayerInfoUtils.GetDefaultAvatarId(playerComp.playerDojo.gender)
        self.avatarId = id
    else
        if id == self.avatarId then--屏蔽相同id
            return
        end
        self.avatarId = id
    end
    ---@type PlayerHeadAvatarVo
    local vo = PlayerInfoUtils.GetHeadAvatarVo(id)

    if vo then
        self:RecyclePoolObj(TYPE.Avatar)
        local resPath = vo.dynamicAvatar
        local isDynamic = not string.isEmpty(resPath)
        if isHideFrame then
            self.frameId = nil
            self:RecyclePoolObj(TYPE.Frame)
            KTool.SetActive(self.ImgFrame, false)
        end
        KTool.SetActive(self.ImgheadIcon, not isDynamic)
        if isDynamic then
            --local PoolManager = CS.Engine.Lib.PoolManager.Instance
            --self.dynamicAvatarGo = PoolManager:GetNew(resPath, true, 1)
            --self.dynamicAvatarGo.transform:SetParent(self.DynamicHead.transform)
            --self.dynamicAvatarGo.transform.localPosition = Vector3.zero
            --self.dynamicAvatarGo.transform.localRotation = Quaternion.identity
            --self.dynamicAvatarGo.transform.localScale = Vector3.one
            --self:SetListObjPoolsName(resPath)
            ResourceModule.LoadGameObjectSync(resPath, function(go)
                if not isNull(go) then
                    self.dynamicAvatarGo = go
                    self.dynamicAvatarGo.transform.localPosition = Vector3.zero
                    self.dynamicAvatarGo.transform.localRotation = Quaternion.identity
                    self.dynamicAvatarGo.transform.localScale = Vector3.one
                end
            end, true, self.DynamicHead.transform)
        else
            CfUtils.FillImage(self.ImgheadIcon, vo.photoPath)
        end
    end
end

---刷新头像框
---@param id string 道具表id
---@param isHideAvatar boolean @ 是否隐藏头像，仅当做纯头像框使用
function CommonPlayerHeadNode:FreshFrame(id, isHideAvatar)
    if checkInt(id) == 0 then
        id = PlayerInfoUtils.GetDefaultAvatarFrameId()
        self.frameId = id
    else
        if id == self.frameId then--屏蔽相同id
            return
        end
        self.frameId = id
    end
    local vo = PlayerInfoUtils.GetHeadAvatarVo(id)
    if vo then
        self:RecyclePoolObj(TYPE.Frame)
        local resPath = vo.dynamicAvatar
        local isDynamic = not string.isEmpty(resPath)
        if isHideAvatar then
            self.avatarId = nil
            self:RecyclePoolObj(TYPE.Avatar)
            KTool.SetActive(self.ImgheadIcon, false)
        end
        KTool.SetActive(self.ImgFrame, not isDynamic)
        if isDynamic then
            ResourceModule.LoadGameObjectSync(resPath, function(go)
                if not isNull(go) then
                    self.dynamicFrameGo = go
                    self.dynamicFrameGo.transform.localPosition = Vector3.zero
                    self.dynamicFrameGo.transform.localRotation = Quaternion.identity
                    self.dynamicFrameGo.transform.localScale = Vector3.one
                end
            end, true, self.DynamicFrame.transform)
            --local PoolManager = CS.Engine.Lib.PoolManager.Instance
            --self.dynamicFrameGo = PoolManager:GetNew(resPath, true, 1)
            --self.dynamicFrameGo.transform:SetParent(self.DynamicFrame.transform)
            --self.dynamicFrameGo.transform.localPosition = Vector3.zero
            --self.dynamicFrameGo.transform.localRotation = Quaternion.identity
            --self.dynamicFrameGo.transform.localScale = Vector3.one
            --self:SetListObjPoolsName(resPath)
        else
            CfUtils.FillImage(self.ImgFrame, vo.photoPath)
        end
    end
end

function CommonPlayerHeadNode:FreshCustomHead(headPath, isHideFrame)
    self.avatarId = nil
    self:RecyclePoolObj(TYPE.Avatar)
    if isHideFrame then
        self.frameId = nil
        self:RecyclePoolObj(TYPE.Frame)
        KTool.SetActive(self.ImgFrame, false)
    end
    KTool.SetActive(self.ImgheadIcon, true)
    CfUtils.FillImage(self.ImgheadIcon, headPath)
    
end

function CommonPlayerHeadNode:SetListObjPoolsName(resPath)
    local poolName = resPath
    if table.keyof(self.listObjPoolsName, poolName) == nil then
        table.insert(self.listObjPoolsName, poolName)
    end
end


---是否置灰节点
function CommonPlayerHeadNode:UpdateGrayNode(isGray)
    if isNull(self.dynamicAvatarGo) then
        local headGaryNode = KTool.GetOrAddComponent(self.ImgheadIcon.gameObject, typeof(CS.Engine.UI.UIGrayGraphics))
        if headGaryNode then
            headGaryNode:MarkGray(isGray)
        end
    else
        local normalNode = self.dynamicAvatarGo.transform:Find("Normal")
        local lockNode = self.dynamicAvatarGo.transform:Find("Lock")
        KTool.SetActive(normalNode, not isGray)
        KTool.SetActive(lockNode, isGray)
    end


    if isNull(self.dynamicFrameGo) then
        local frameGaryNode = KTool.GetOrAddComponent(self.ImgFrame.gameObject, typeof(CS.Engine.UI.UIGrayGraphics))
        if frameGaryNode then
            frameGaryNode:MarkGray(isGray)
        end
    else
        local normalNode = self.dynamicFrameGo.transform:Find("Normal")
        local lockNode = self.dynamicFrameGo.transform:Find("Lock")
        KTool.SetActive(normalNode, not isGray)
        KTool.SetActive(lockNode, isGray)
    end
end

function CommonPlayerHeadNode:RecyclePoolObj(type)
    local PoolManager = CS.Engine.Lib.PoolManager.Instance
    local list = {}
    if type == TYPE.Avatar then
        if not IsNull(self.dynamicAvatarGo) then
            table.insert(list, self.dynamicAvatarGo.gameObject)
            self.dynamicAvatarGo = nil
        end
    elseif type == TYPE.Frame then
        if not IsNull(self.dynamicFrameGo) then
            table.insert(list, self.dynamicFrameGo.gameObject)
            self.dynamicFrameGo = nil
        end
    else--不传则全部回收
        if not IsNull(self.dynamicAvatarGo) then
            table.insert(list, self.dynamicAvatarGo.gameObject)
            self.dynamicAvatarGo = nil
        end
        if not IsNull(self.dynamicFrameGo) then
            table.insert(list, self.dynamicFrameGo.gameObject)
            self.dynamicFrameGo = nil
        end
    end
    for i, v in pairs(list) do
        CS.UnityEngine.GameObject.Destroy(v.gameObject)
        --PoolManager:GiveBack(v)
    end
end

function CommonPlayerHeadNode:ClearObjPools()
    local PoolManager = CS.Engine.Lib.PoolManager.Instance
    for i, v in pairs(self.listObjPoolsName) do
        PoolManager:TearDown(v)
    end

end


function CommonPlayerHeadNode:OnDestroy()
    self:RecyclePoolObj()
    --self:ClearObjPools()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return CommonPlayerHeadNode